const payload = $input.item.json.body || $input.item.json;
if (payload.object !== 'whatsapp_business_account') {
  return [];
}

const normalized = [];
const entries = payload.entry || [];
for (const entry of entries) {
  for (const change of (entry.changes || [])) {
    const val = change.value || {};
    const metadata = val.metadata || {};
    const contacts = val.contacts || [];
    const contactName = contacts.length > 0 ? (contacts[0].profile ? contacts[0].profile.name : 'Lead') : 'Lead';
    const messages = val.messages || [];

    for (const msg of messages) {
      let textBody = '';
      if (msg.type === 'text') {
        textBody = msg.text ? msg.text.body : '';
      } else if (msg.type === 'button') {
        textBody = msg.button ? msg.button.text : '';
      } else if (msg.type === 'interactive') {
        textBody = msg.interactive?.button_reply?.title || '';
      } else {
        textBody = `[${msg.type.toUpperCase()}]`;
      }

      normalized.push({
        json: {
          provider: 'meta_whatsapp',
          event_type: 'message_received',
          business_phone_id: metadata.phone_number_id,
          meta_message_id: msg.id,
          wa_id: msg.from,
          contact_name: contactName,
          message_type: msg.type,
          message_text: textBody,
          received_at: new Date(parseInt(msg.timestamp) * 1000).toISOString(),
          is_opt_out: /\b(stop|cancel|unsubscribe|parar|baja|no\s*mas)\b/i.test(textBody),
          is_human_request: /\b(human|humano|persona|asesor|soporte|agent)\b/i.test(textBody)
        }
      });
    }
  }
}
return normalized;
